import { createInterface } from 'node:readline';

const MAX = Number(process.env.MAX || 700);
const rl = createInterface({ input: process.stdin });
let i = 0;
for await (const line of rl) {
  if (!line.trim()) continue;
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  i++;
  const ts = (e.timestamp || '').replace(/^.*T/, '').replace(/\..*$/, '');
  const m = e.message;
  if (!m) {
    console.log(`[${i}] ${ts} <${e.type || 'meta'}>`);
    continue;
  }
  const role = m.role || e.type;
  const parts = Array.isArray(m.content) ? m.content : [{ type: 'text', text: String(m.content ?? '') }];
  for (const p of parts) {
    if (p.type === 'text') {
      const t = (p.text || '').trim();
      if (t) console.log(`[${i}] ${ts} ${role}: ${t.length > MAX ? t.slice(0, MAX) + ' …[+' + (t.length - MAX) + ']' : t}`);
    } else if (p.type === 'thinking') {
      const t = (p.thinking || '').trim();
      if (t) console.log(`[${i}] ${ts} ${role}#think: ${t.length > 400 ? t.slice(0, 400) + ' …' : t}`);
    } else if (p.type === 'tool_use') {
      const inp = JSON.stringify(p.input || {});
      console.log(`[${i}] ${ts} ${role}=TOOL ${p.name}: ${inp.length > 400 ? inp.slice(0, 400) + ' …' : inp}`);
    } else if (p.type === 'tool_result') {
      let c = p.content;
      if (Array.isArray(c)) c = c.map(x => x.text || `<${x.type}>`).join(' ');
      c = String(c ?? '').replace(/\s+/g, ' ').trim();
      console.log(`[${i}] ${ts} RESULT${p.is_error ? '(ERR)' : ''}: ${c.length > 300 ? c.slice(0, 300) + ' …' : c}`);
    }
  }
}

